function requestcontrol_000d.dissector(buffer, pinfo, tree)
	-- /home/tiderko/tmp/jsidl_xml/urn.jaus.jss.core/urn_jaus_jss_core_AccessControl.xml
	local bufidx = 0
	messageid = buffer(bufidx, 2):le_uint()
	local tree_msg = tree:add(pf_message_name, buffer(), "RequestControl", string.format("RequestControl, MessageID: %04X, %d bytes", messageid, buffer:len()))
	pinfo.cols.info:set(string.format("%s %s", tostring(pinfo.cols.info), "RequestControl"))
	tree_msg:add(pf_messageid, buffer(bufidx, 2), messageid, string.format('Header, MessageID: 0x%04X -- (unsigned short integer) A two byte field to hold the message ID of a message', messageid))
	bufidx = bufidx + 2
	local body_tree = tree_msg:add(buffer(bufidx, buffer:len() - bufidx), "Body")
	local body_RequestControlRec_tree = body_tree:add("RequestControlRec")
	local value_set = {}
	local value_id, value_name = (value_set[buffer(bufidx, 1):le_uint()])
	body_RequestControlRec_tree:add(buffer(bufidx, 1), string.format("AuthorityCode: %d [%s] -- (unsigned byte)", buffer(bufidx, 1):le_uint(), value_id))
	bufidx = bufidx + 1
end
messagetable:add(0x000D, requestcontrol_000d)

